// Procedural pixel-art generator for the placeholder cat. Run: npm run sprites
// Writes assets/sprites/cat.png (sprite sheet), cat-preview.png (4x preview) and the tray template icons.
// Original artwork generated by code; no third-party assets.
import { mkdirSync, writeFileSync } from 'node:fs'
import zlib from 'node:zlib'

const F = 40 // frame size in px
// Sheet layout: one row per animation. `ms` is the time each frame is shown.
const ROWS = [
  { name: 'idle', frames: 12, ms: 130 },
  { name: 'walk', frames: 10, ms: 90 },
  { name: 'curious', frames: 8, ms: 120 },
  { name: 'thinking', frames: 8, ms: 220 },
  { name: 'speaking', frames: 8, ms: 90 },
  { name: 'sleeping', frames: 8, ms: 420 },
  { name: 'listening', frames: 8, ms: 160 }
]
const IDLE_FRAMES = ROWS[0].frames
const WALK_FRAMES = ROWS[1].frames
const COLS = Math.max(...ROWS.map((r) => r.frames))

const P = {
  outline: [20, 48, 90],
  deep: [32, 80, 143],
  dark: [44, 99, 176],
  base: [63, 134, 224],
  light: [140, 192, 245],
  belly: [234, 246, 255],
  bellyDark: [188, 211, 236],
  pink: [232, 84, 138],
  earIn: [242, 160, 192],
  white: [255, 255, 255]
}
const RAMP = [P.deep, P.dark, P.base, P.light] // darkest -> lightest
const BELLY_RAMP = [P.bellyDark, P.bellyDark, P.belly, P.white]

class Img {
  constructor(w, h) {
    this.w = w
    this.h = h
    this.d = new Uint8Array(w * h * 4)
  }
  set(x, y, c, a = 255) {
    if (x < 0 || y < 0 || x >= this.w || y >= this.h) return
    const i = (y * this.w + x) * 4
    this.d[i] = c[0]
    this.d[i + 1] = c[1]
    this.d[i + 2] = c[2]
    this.d[i + 3] = a
  }
  alpha(x, y) {
    if (x < 0 || y < 0 || x >= this.w || y >= this.h) return 0
    return this.d[(y * this.w + x) * 4 + 3]
  }
}

// ---- shape helpers: each returns {inside(x,y), lum(x,y)} with lum in [-1,1] (light from top-left) ----
const ellipse = (cx, cy, rx, ry) => ({
  inside: (x, y) => ((x - cx) / rx) ** 2 + ((y - cy) / ry) ** 2 <= 1,
  lum: (x, y) => -(((x - cx) / rx) * 0.45 + ((y - cy) / ry) * 0.8)
})
const capsule = (ax, ay, bx, by, r) => {
  const dx = bx - ax
  const dy = by - ay
  const len2 = dx * dx + dy * dy || 1
  const proj = (x, y) => {
    const t = Math.max(0, Math.min(1, ((x - ax) * dx + (y - ay) * dy) / len2))
    return [ax + t * dx, ay + t * dy]
  }
  return {
    inside: (x, y) => {
      const [px, py] = proj(x, y)
      return Math.hypot(x - px, y - py) <= r
    },
    lum: (x, y) => {
      const [px, py] = proj(x, y)
      return -((x - px) * 0.55 + (y - py) * 0.6) / r
    }
  }
}
const tri = (a, b, c) => {
  const sign = (p, q, r) => (p[0] - r[0]) * (q[1] - r[1]) - (q[0] - r[0]) * (p[1] - r[1])
  return {
    inside: (x, y) => {
      const p = [x, y]
      const d1 = sign(p, a, b)
      const d2 = sign(p, b, c)
      const d3 = sign(p, c, a)
      return !((d1 < 0 || d2 < 0 || d3 < 0) && (d1 > 0 || d2 > 0 || d3 > 0))
    },
    lum: (x, y) => -((x - (a[0] + b[0] + c[0]) / 3) * 0.12 + (y - (a[1] + b[1] + c[1]) / 3) * 0.1)
  }
}
const chain = (circles) => ({
  inside: (x, y) => circles.some((c) => (x - c.x) ** 2 + (y - c.y) ** 2 <= c.r * c.r),
  lum: (x, y) => {
    let best = null
    let bd = 1e9
    for (const c of circles) {
      const d = ((x - c.x) ** 2 + (y - c.y) ** 2) / (c.r * c.r)
      if (d <= 1 && d < bd) {
        bd = d
        best = c
      }
    }
    return best ? -(((x - best.x) / best.r) * 0.45 + ((y - best.y) / best.r) * 0.8) : 0
  }
})

const toneIdx = (lum, shift = 0) => {
  let i = lum > 0.5 ? 3 : lum > -0.15 ? 2 : lum > -0.6 ? 1 : 0
  return Math.max(0, Math.min(3, i + shift))
}

/** Paint a shape. opts: ramp, shift (tone offset), outline (bool), clip(x,y) */
function paint(img, shape, { ramp = RAMP, shift = 0, outline = true, clip = null, override = null } = {}) {
  const mask = new Uint8Array(img.w * img.h)
  for (let y = 0; y < img.h; y++) {
    for (let x = 0; x < img.w; x++) {
      if (shape.inside(x + 0.5, y + 0.5) && (!clip || clip(x + 0.5, y + 0.5))) mask[y * img.w + x] = 1
    }
  }
  const at = (x, y) => (x < 0 || y < 0 || x >= img.w || y >= img.h ? 0 : mask[y * img.w + x])
  if (outline) {
    for (let y = 0; y < img.h; y++) {
      for (let x = 0; x < img.w; x++) {
        if (!at(x, y) && (at(x - 1, y) || at(x + 1, y) || at(x, y - 1) || at(x, y + 1))) img.set(x, y, P.outline)
      }
    }
  }
  for (let y = 0; y < img.h; y++) {
    for (let x = 0; x < img.w; x++) {
      if (!at(x, y)) continue
      const c = override ? override(x + 0.5, y + 0.5) : ramp[toneIdx(shape.lum(x + 0.5, y + 0.5), shift)]
      img.set(x, y, c)
    }
  }
}

function line(img, x0, y0, x1, y1, c) {
  const n = Math.max(Math.abs(x1 - x0), Math.abs(y1 - y0)) || 1
  for (let i = 0; i <= n; i++) img.set(Math.round(x0 + ((x1 - x0) * i) / n), Math.round(y0 + ((y1 - y0) * i) / n), c)
}

const GROUND = 35.5 // y of the foot centre; sprite rows below 37 stay empty (see groundMarginRows in cat.json)

// 3x5 pixel glyphs for the little markers above the head
const GLYPHS = {
  '?': ['111', '001', '011', '000', '010'],
  '!': ['010', '010', '010', '000', '010'],
  z: ['111', '001', '010', '100', '111']
}
function glyph(img, ch, x0, y0, c = P.outline, scale = 1) {
  const g = GLYPHS[ch]
  g.forEach((row, gy) =>
    [...row].forEach((bit, gx) => {
      if (bit !== '1') return
      for (let dy = 0; dy < scale; dy++) for (let dx = 0; dx < scale; dx++) img.set(x0 + gx * scale + dx, y0 + gy * scale + dy, c)
    })
  )
}
/** Little sound-wave arcs: n of them, growing outwards. */
const waves = (img, n, x0, y0) => {
  for (let i = 0; i < n; i++) {
    const h = 2 + i * 2 // half-height grows with each arc
    for (let dy = -h; dy <= h; dy++) {
      const bend = Math.abs(dy) >= h - 1 && h > 2 ? 1 : 0
      img.set(x0 + i * 3 - bend, y0 + dy, P.outline)
    }
  }
}
const dots = (img, n, x0, y0) => {
  for (let i = 0; i < n; i++) {
    img.set(x0 + i * 4, y0, P.outline)
    img.set(x0 + i * 4 + 1, y0, P.outline)
    img.set(x0 + i * 4, y0 + 1, P.outline)
    img.set(x0 + i * 4 + 1, y0 + 1, P.outline)
  }
}

/** Ears + head + face, shared by the standing and lying poses. */
function drawHead(img, hx, hy, { blink = false, closed = false, mouth = 0, lookUp = false, earLift = 0, rx = 8.5, ry = 7.5 } = {}) {
  const farEar = [
    [hx - 6, hy - 3],
    [hx - 5, hy - 11.5 - earLift],
    [hx - 0.5, hy - 6]
  ]
  const nearEar = [
    [hx + 1.5, hy - 6],
    [hx + 5.5, hy - 12 - earLift],
    [hx + 7.5, hy - 2.5]
  ]
  paint(img, tri(...farEar), { shift: -1 })
  paint(img, tri(...nearEar))
  const shrink = (t) => {
    const cx = (t[0][0] + t[1][0] + t[2][0]) / 3
    const cy = (t[0][1] + t[1][1] + t[2][1]) / 3 + 1
    return t.map(([x, y]) => [cx + (x - cx) * 0.5, cy + (y - cy) * 0.5])
  }
  paint(img, tri(...shrink(farEar)), { outline: false, override: () => P.earIn })
  paint(img, tri(...shrink(nearEar)), { outline: false, override: () => P.earIn })

  // cheek fur tufts and a forehead tuft (drawn before the head so the head's face overlaps their roots)
  paint(img, tri([hx + 3, hy + 3], [hx + 11.5, hy + 6.2], [hx + 5, hy + 8.4]), { shift: 1 })
  paint(img, tri([hx - 7, hy + 2], [hx - 10.5, hy + 5.8], [hx - 3.5, hy + 6.8]), { shift: -1 })
  paint(img, tri([hx - 1.5, hy - 5.5], [hx + 1.2, hy - 10.2 - earLift * 0.4], [hx + 3.5, hy - 5.5]))
  const head = ellipse(hx, hy, rx, ry)
  paint(img, head)
  paint(img, ellipse(hx + 6.2, hy + 3.2, 3.8, 2.9), {
    outline: false,
    ramp: [P.light, P.light, P.light, P.belly],
    clip: (x, y) => head.inside(x, y)
  })
  const ex = hx + 3.6
  const ey = hy - 1.2
  if (closed) {
    // relaxed, closed eye (sleeping): a small downward arc
    line(img, Math.round(ex - 1.8), Math.round(ey + 0.5), Math.round(ex + 2), Math.round(ey + 0.5), P.outline)
    img.set(Math.round(ex - 1.8), Math.round(ey), P.outline)
    img.set(Math.round(ex + 2), Math.round(ey), P.outline)
  } else if (blink) {
    line(img, Math.round(ex - 1.8), Math.round(ey + 0.5), Math.round(ex + 2), Math.round(ey + 0.5), P.outline)
  } else {
    paint(img, ellipse(ex, ey, 2.3, 2.9), { outline: true, override: () => P.white })
    const up = lookUp ? -1.1 : 0
    paint(img, ellipse(ex + 0.7, ey + 0.5 + up, 1.3, 1.9), { outline: false, override: () => P.outline })
    img.set(Math.round(ex + 0.2), Math.round(ey - 0.9 + up), P.white)
  }
  // nose, mouth, whiskers
  img.set(Math.round(hx + 8.4), Math.round(hy + 1.2), P.pink)
  img.set(Math.round(hx + 7.4), Math.round(hy + 1.2), P.pink)
  if (mouth > 0) {
    // open mouth: dark oval with a pink tongue
    paint(img, ellipse(hx + 7.6, hy + 4.6, 1.6 + mouth * 0.5, 0.9 + mouth * 0.9), { outline: false, override: () => P.outline })
    img.set(Math.round(hx + 7.6), Math.round(hy + 4.6 + mouth * 0.8), P.pink)
  } else {
    img.set(Math.round(hx + 7.4), Math.round(hy + 4.2), P.outline)
    img.set(Math.round(hx + 8.4), Math.round(hy + 4.2), P.outline)
  }
  line(img, Math.round(hx + 8.2), Math.round(hy + 2.6), Math.round(hx + 12), Math.round(hy + 1.2), P.outline)
  line(img, Math.round(hx + 8.2), Math.round(hy + 3.4), Math.round(hx + 12), Math.round(hy + 4.6), P.outline)
}

function renderCat({ bob = 0, tail = 0, blink = false, legs, mouth = 0, lookUp = false, earLift = 0, headDy = 0, decorate = null }) {
  const img = new Img(F, F)
  const by = 24 + bob // body centre y
  const hx = 27
  const hy = 15 + bob + headDy // head centre

  // tail (behind everything)
  const circles = []
  for (let i = 0; i <= 9; i++) {
    const t = i / 9
    const p0 = [8, by - 1]
    const p1 = [-1, by - 3]
    const p2 = [3 + tail * 2.5, 9 + bob]
    const x = (1 - t) ** 2 * p0[0] + 2 * (1 - t) * t * p1[0] + t * t * p2[0]
    const y = (1 - t) ** 2 * p0[1] + 2 * (1 - t) * t * p1[1] + t * t * p2[1]
    circles.push({ x, y, r: 2.7 - 0.9 * t })
  }
  paint(img, chain(circles))
  // tabby rings and a pale tip: extra shapes laid over the tail
  const ring = (idx, c) => paint(img, chain(idx.map((i) => circles[i])), { outline: false, override: () => c })
  ring([2, 3, 5, 6], P.deep)
  ring([9], P.belly)

  const paintLeg = (hipX, l, shift) => {
    const foot = [hipX + l.sw, GROUND - l.lift]
    const shape = capsule(hipX, by + 3, foot[0], foot[1], 2.3)
    paint(img, shape, {
      override: (x, y) => {
        if (y > foot[1] - 2.2) return shift < 0 ? P.bellyDark : P.belly
        return RAMP[toneIdx(shape.lum(x, y), shift)]
      }
    })
    // toe separators
    img.set(Math.round(foot[0] - 0.5), Math.round(foot[1] + 0.5), P.bellyDark)
    img.set(Math.round(foot[0] + 1), Math.round(foot[1] + 0.5), P.bellyDark)
  }
  paintLeg(12.5, legs.fb, -1)
  paintLeg(20.5, legs.ff, -1)

  const body = ellipse(16, by, 11, 7)
  paint(img, body)
  paint(img, ellipse(18.5, by + 4, 8, 3.6), { outline: false, ramp: BELLY_RAMP, clip: (x, y) => body.inside(x, y) })
  // tabby stripes down the back (slanted polygons clipped to the body) and a chest tuft
  for (const sx of [8, 12.5, 17, 21.5]) {
    paint(img, tri([sx, by - 8], [sx + 3, by - 8], [sx + 1.2, by - 1.5]), { outline: false, override: () => P.deep, clip: (x, y) => body.inside(x, y) })
  }
  paint(img, tri([23.5, by + 0.5], [28, by + 5.5], [21.5, by + 6.5]), { outline: false, ramp: BELLY_RAMP, shift: 1, clip: (x, y) => body.inside(x, y) })

  paintLeg(9.5, legs.nb, 0)
  paintLeg(23.5, legs.nf, 0)

  drawHead(img, hx, hy, { blink, mouth, lookUp, earLift })
  if (decorate) decorate(img)
  return img
}

/** Lying-down pose for the sleeping animation: slow continuous breathing, two Zs drifting up and out. */
function renderSleeping(f) {
  const img = new Img(F, F)
  const n = ROWS[5].frames
  const p = f / n
  const breath = 0.5 - 0.5 * Math.cos(2 * Math.PI * p) // 0..1..0 over one loop
  const hx = 28
  const hy = 29 - breath * 0.5
  // tail curled around the front, drawn first so the body overlaps its base
  const circles = []
  for (let i = 0; i <= 10; i++) {
    const t = i / 10
    const p0 = [6, 31]
    const p1 = [8, 40]
    const p2 = [27, 37]
    const x = (1 - t) ** 2 * p0[0] + 2 * (1 - t) * t * p1[0] + t * t * p2[0]
    const y = (1 - t) ** 2 * p0[1] + 2 * (1 - t) * t * p1[1] + t * t * p2[1]
    circles.push({ x, y: Math.min(y, 35), r: 2.4 - 0.5 * t })
  }
  const body = ellipse(16, 31 - breath * 0.6, 12.5, 5.6 + breath * 0.9)
  paint(img, body)
  paint(img, ellipse(17, 34, 9, 2.4), { outline: false, ramp: BELLY_RAMP, clip: (x, y) => body.inside(x, y) })
  for (const sx of [9, 13.5, 18, 22.5]) {
    paint(img, tri([sx, 25], [sx + 3, 25], [sx + 1.2, 30]), { outline: false, override: () => P.deep, clip: (x, y) => body.inside(x, y) })
  }
  paint(img, chain(circles))
  paint(img, chain([circles[3], circles[4], circles[6], circles[7]]), { outline: false, override: () => P.deep })
  // front paws tucked under the chin
  paint(img, ellipse(31, 35.4, 3.6, 1.8), { ramp: BELLY_RAMP })
  drawHead(img, hx, hy, { closed: true, rx: 8.5, ry: 6.6, earLift: -3 })
  // two Zs, half a loop apart: each rises and drifts right, and is only drawn while inside the frame
  for (const off of [0, 0.5]) {
    const t = (p + off) % 1
    const y = Math.round(20 - t * 16)
    const x = Math.round(32 + t * 5)
    if (t > 0.08 && y >= 1) glyph(img, 'z', x, y, P.outline, 1)
  }
  return img
}

const stand = { sw: 0, lift: 0 }
const standing = { nf: stand, ff: stand, nb: stand, fb: stand }
const TAU = 2 * Math.PI
const ease = (p) => 0.5 - 0.5 * Math.cos(TAU * p) // 0 -> 1 -> 0 over one loop, smooth at both ends

// idle: slow breathing, the head following a beat later, the tail swaying, an occasional ear twitch and blink
const idleFrame = (f) => {
  const n = ROWS[0].frames
  const p = f / n
  return renderCat({
    bob: 0.9 * ease(p),
    headDy: 0.5 * ease(p - 0.12),
    tail: Math.sin(TAU * p),
    blink: f === 9,
    earLift: f === 5 || f === 6 ? 0.9 : 0,
    legs: standing
  })
}
// walk: continuous leg swing, double-frequency body bounce, head and tail counter-moving
const walkFrame = (f) => {
  const phi = (TAU * f) / ROWS[1].frames
  const mk = (ph) => ({ sw: 3.4 * Math.sin(ph), lift: 2.8 * Math.max(0, Math.cos(ph)) })
  const a = mk(phi)
  const b = mk(phi + Math.PI)
  return renderCat({ bob: 0.9 * Math.abs(Math.sin(phi)), headDy: -0.4 * Math.abs(Math.sin(phi)), tail: Math.sin(phi) * 0.9, legs: { nf: a, fb: a, ff: b, nb: b } })
}
// alert: ears up, eyes looking up, tail flicking, a "?" bobbing beside the head
const curiousFrame = (f) => {
  const p = f / ROWS[2].frames
  return renderCat({
    bob: 0,
    tail: Math.sin(TAU * p * 2) * 0.9,
    lookUp: true,
    earLift: 1 + 0.5 * ease(p * 2),
    headDy: -1 - 0.3 * ease(p),
    legs: standing,
    decorate: (img) => glyph(img, '?', 16, 3 - Math.round(ease(p * 2)), P.outline)
  })
}
// thinking: gaze up, slow head bob, "..." filling in above one dot at a time
const thinkingFrame = (f) => {
  const p = f / ROWS[3].frames
  return renderCat({
    bob: 0.7 * ease(p),
    tail: 0.5 * Math.sin(TAU * p),
    lookUp: true,
    headDy: -0.5 - 0.5 * ease(p + 0.25),
    legs: standing,
    decorate: (img) => dots(img, Math.floor(f / 2), 14, 6)
  })
}
// listening: ears up, head cocked towards the user, sound waves growing beside the head
const listeningFrame = (f) => {
  const p = f / ROWS[6].frames
  return renderCat({
    bob: 0,
    tail: 0.6 * Math.sin(TAU * p),
    earLift: 1 + 0.4 * ease(p * 2),
    headDy: -1,
    legs: standing,
    decorate: (img) => waves(img, [1, 1, 2, 3, 3, 2, 2, 1][f], 13, 8)
  })
}
// speaking: the mouth opens and closes twice a loop, the head nodding with it
const speakingFrame = (f) => {
  const p = f / ROWS[4].frames
  const open = ease(p * 2) // 0 -> 1 -> 0 twice
  return renderCat({ bob: 0.5 * open, headDy: -0.4 * open, tail: 0.4 * Math.sin(TAU * p), mouth: open < 0.2 ? 0 : open * 2, legs: standing })
}

// ---- compose the sheet ----
const sheet = new Img(F * COLS, F * ROWS.length)
const blit = (src, col, row) => {
  for (let y = 0; y < F; y++)
    for (let x = 0; x < F; x++) {
      const i = (y * F + x) * 4
      if (src.d[i + 3]) sheet.set(col * F + x, row * F + y, [src.d[i], src.d[i + 1], src.d[i + 2]], src.d[i + 3])
    }
}
const makers = [idleFrame, walkFrame, curiousFrame, thinkingFrame, speakingFrame, renderSleeping, listeningFrame]
ROWS.forEach((r, row) => {
  for (let f = 0; f < r.frames; f++) blit(makers[row](f), f, row)
})

// ---- PNG writer ----
function png(img) {
  const raw = Buffer.alloc((img.w * 4 + 1) * img.h)
  for (let y = 0; y < img.h; y++) {
    raw[y * (img.w * 4 + 1)] = 0
    Buffer.from(img.d.buffer, y * img.w * 4, img.w * 4).copy(raw, y * (img.w * 4 + 1) + 1)
  }
  const chunk = (type, data) => {
    const len = Buffer.alloc(4)
    len.writeUInt32BE(data.length)
    const td = Buffer.concat([Buffer.from(type), data])
    const crc = Buffer.alloc(4)
    crc.writeUInt32BE(zlib.crc32(td) >>> 0)
    return Buffer.concat([len, td, crc])
  }
  const ihdr = Buffer.alloc(13)
  ihdr.writeUInt32BE(img.w, 0)
  ihdr.writeUInt32BE(img.h, 4)
  ihdr[8] = 8
  ihdr[9] = 6
  return Buffer.concat([
    Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]),
    chunk('IHDR', ihdr),
    chunk('IDAT', zlib.deflateSync(raw, { level: 9 })),
    chunk('IEND', Buffer.alloc(0))
  ])
}
const scaled = (img, k, bg) => {
  const out = new Img(img.w * k, img.h * k)
  for (let y = 0; y < out.h; y++)
    for (let x = 0; x < out.w; x++) {
      const sx = Math.floor(x / k)
      const sy = Math.floor(y / k)
      const i = (sy * img.w + sx) * 4
      if (img.d[i + 3]) out.set(x, y, [img.d[i], img.d[i + 1], img.d[i + 2]], img.d[i + 3])
      else if (bg) out.set(x, y, bg)
    }
  return out
}

// ---- tray template icon: black silhouette of a cat head, alpha only ----
function trayIcon(size) {
  const img = new Img(size, size)
  const s = size / 16
  const head = ellipse(8 * s, 9.5 * s, 6 * s, 5 * s)
  const e1 = tri([2.5 * s, 7 * s], [3.2 * s, 1.5 * s], [7 * s, 5 * s])
  const e2 = tri([13.5 * s, 7 * s], [12.8 * s, 1.5 * s], [9 * s, 5 * s])
  for (let y = 0; y < size; y++)
    for (let x = 0; x < size; x++) {
      const px = x + 0.5
      const py = y + 0.5
      if (head.inside(px, py) || e1.inside(px, py) || e2.inside(px, py)) img.set(x, y, [0, 0, 0], 255)
    }
  return img
}

mkdirSync('assets/sprites', { recursive: true })
mkdirSync('assets/tray', { recursive: true })
writeFileSync('assets/sprites/cat.png', png(sheet))
writeFileSync('assets/sprites/cat-preview.png', png(scaled(sheet, 4, [200, 205, 215])))
writeFileSync('assets/tray/trayTemplate.png', png(trayIcon(16)))
writeFileSync('assets/tray/trayTemplate@2x.png', png(trayIcon(32)))
// lowest opaque row across the standing frames -> how many empty rows sit under the feet (used to stand on the Dock edge)
let lowest = 0
for (let y = 0; y < F * 2; y++) for (let x = 0; x < sheet.w; x++) if (sheet.alpha(x, y)) lowest = Math.max(lowest, y % F)
writeFileSync(
  'assets/sprites/cat.json',
  JSON.stringify(
    {
      frame: F,
      cols: COLS,
      rows: Object.fromEntries(ROWS.map((r, i) => [r.name, { row: i, frames: r.frames, ms: r.ms }])),
      groundMarginRows: F - 1 - lowest
    },
    null,
    2
  ) + '\n'
)
console.log(`sprites written: ${sheet.w}x${sheet.h} sheet, frame ${F}px, rows: ${ROWS.map((r) => r.name).join(', ')}`)
